create extension if not exists pgcrypto;
create type public.app_role as enum ('admin','organizer','judge','display');
create type public.competition_model as enum ('sum_score','digital_flags');
create type public.event_status as enum ('draft','registration_open','registration_closed','preparing','live','finished','archived');

create table public.organizations (id uuid primary key default gen_random_uuid(), name text not null, slug text unique not null, settings jsonb not null default '{}', created_at timestamptz not null default now());
create table public.profiles (id uuid primary key references auth.users on delete cascade, full_name text not null, phone text, created_at timestamptz not null default now());
create table public.user_roles (user_id uuid references public.profiles on delete cascade, organization_id uuid references public.organizations on delete cascade, role public.app_role not null, primary key(user_id, organization_id, role));
create table public.events (id uuid primary key default gen_random_uuid(), organization_id uuid not null references public.organizations on delete cascade, name text not null, slug text not null, edition text, description text, starts_at timestamptz, ends_at timestamptz, venue text, city text, status public.event_status not null default 'draft', settings jsonb not null default '{}', published_at timestamptz, created_by uuid references public.profiles, created_at timestamptz not null default now(), unique(organization_id,slug));
create table public.event_users (event_id uuid references public.events on delete cascade, user_id uuid references public.profiles on delete cascade, role public.app_role not null, primary key(event_id,user_id,role));
create table public.competition_templates (id uuid primary key default gen_random_uuid(), organization_id uuid references public.organizations on delete cascade, name text not null, model public.competition_model not null, settings jsonb not null default '{}');
create table public.competitions (id uuid primary key default gen_random_uuid(), event_id uuid not null references public.events on delete cascade, name text not null, model public.competition_model not null, settings jsonb not null default '{}', status text not null default 'draft');
create table public.categories (id uuid primary key default gen_random_uuid(), competition_id uuid not null references public.competitions on delete cascade, name text not null, code text, sort_order int not null default 0, settings jsonb not null default '{}', status text not null default 'draft');
create table public.participants (id uuid primary key default gen_random_uuid(), organization_id uuid not null references public.organizations on delete cascade, full_name text not null, birth_date date, private_data jsonb not null default '{}', created_at timestamptz not null default now());
create table public.registrations (id uuid primary key default gen_random_uuid(), event_id uuid not null references public.events on delete cascade, participant_id uuid not null references public.participants on delete cascade, category_id uuid not null references public.categories, data jsonb not null default '{}', attendance_confirmed boolean not null default false, payment_confirmed boolean not null default false, unique(event_id,participant_id,category_id));
create table public.rings (id uuid primary key default gen_random_uuid(), event_id uuid not null references public.events on delete cascade, name text not null, status text not null default 'preparing', settings jsonb not null default '{}');
create table public.judge_assignments (id uuid primary key default gen_random_uuid(), event_id uuid not null references public.events on delete cascade, competition_id uuid not null references public.competitions on delete cascade, category_id uuid references public.categories, ring_id uuid references public.rings, judge_id uuid not null references public.profiles, active boolean not null default true, starts_at timestamptz, ends_at timestamptz);
create table public.scoring_criteria (id uuid primary key default gen_random_uuid(), competition_id uuid not null references public.competitions on delete cascade, name text not null, description text, min_score numeric not null default 0, max_score numeric not null default 10, sort_order int not null default 0, tiebreak_order int);
create table public.presentations (id uuid primary key default gen_random_uuid(), category_id uuid not null references public.categories on delete cascade, registration_id uuid not null references public.registrations, sort_order int not null, status text not null default 'waiting');
create table public.scorecards (id uuid primary key default gen_random_uuid(), presentation_id uuid not null references public.presentations on delete cascade, judge_id uuid not null references public.profiles, assignment_id uuid not null references public.judge_assignments, note text, submitted_at timestamptz not null default now(), unique(presentation_id,judge_id));
create table public.score_items (scorecard_id uuid references public.scorecards on delete cascade, criterion_id uuid references public.scoring_criteria, score numeric not null check(score between 0 and 10), primary key(scorecard_id,criterion_id));
create table public.matches (id uuid primary key default gen_random_uuid(), category_id uuid not null references public.categories on delete cascade, ring_id uuid not null references public.rings, blue_registration_id uuid not null references public.registrations, green_registration_id uuid not null references public.registrations, phase text not null, status text not null default 'waiting', winner_registration_id uuid references public.registrations, started_at timestamptz, finished_at timestamptz);
create table public.flag_votes (id uuid primary key default gen_random_uuid(), match_id uuid not null references public.matches on delete cascade, judge_id uuid not null references public.profiles, assignment_id uuid not null references public.judge_assignments, chosen_registration_id uuid not null references public.registrations, color text not null check(color in ('blue','green')), created_at timestamptz not null default now(), unique(match_id,judge_id));
create table public.regulations (id uuid primary key default gen_random_uuid(), event_id uuid not null references public.events on delete cascade, competition_id uuid references public.competitions, category_id uuid references public.categories, current_version int not null default 1);
create table public.regulation_versions (id uuid primary key default gen_random_uuid(), regulation_id uuid not null references public.regulations on delete cascade, version int not null, content text not null, reason text, changed_by uuid references public.profiles, created_at timestamptz not null default now(), unique(regulation_id,version));
create table public.results (id uuid primary key default gen_random_uuid(), category_id uuid not null references public.categories, registration_id uuid not null references public.registrations, position int, total numeric, homologated_at timestamptz, homologated_by uuid references public.profiles, published_at timestamptz, details jsonb not null default '{}');
create table public.podiums (id uuid primary key default gen_random_uuid(), category_id uuid not null references public.categories, revealed_at timestamptz, settings jsonb not null default '{}');
create table public.audit_logs (id bigint generated always as identity primary key, actor_id uuid references public.profiles, event_id uuid references public.events, action text not null, entity_type text not null, entity_id uuid, details jsonb not null default '{}', created_at timestamptz not null default now());
create index events_org_idx on public.events(organization_id); create index competitions_event_idx on public.competitions(event_id); create index categories_comp_idx on public.categories(competition_id); create index votes_match_idx on public.flag_votes(match_id); create index scores_presentation_idx on public.scorecards(presentation_id);

create or replace function public.is_admin(org uuid) returns boolean language sql stable security definer set search_path=public as $$ select exists(select 1 from user_roles where user_id=auth.uid() and organization_id=org and role='admin') $$;
create or replace function public.can_manage_event(eid uuid) returns boolean language sql stable security definer set search_path=public as $$ select exists(select 1 from events e where e.id=eid and (is_admin(e.organization_id) or exists(select 1 from event_users eu where eu.event_id=e.id and eu.user_id=auth.uid() and eu.role='organizer'))) $$;

alter table public.events enable row level security; alter table public.participants enable row level security; alter table public.flag_votes enable row level security; alter table public.scorecards enable row level security; alter table public.results enable row level security;
create policy "public published events" on public.events for select using (published_at is not null or can_manage_event(id) or exists(select 1 from event_users where event_id=id and user_id=auth.uid()));
create policy "managers write events" on public.events for all using (can_manage_event(id)) with check (is_admin(organization_id) or exists(select 1 from event_users where event_id=id and user_id=auth.uid() and role='organizer'));
create policy "authorized score submission" on public.scorecards for insert with check (judge_id=auth.uid() and exists(select 1 from judge_assignments ja join presentations p on p.category_id=ja.category_id where ja.id=assignment_id and ja.judge_id=auth.uid() and ja.active and p.id=presentation_id));
create policy "authorized isolated vote" on public.flag_votes for insert with check (judge_id=auth.uid() and exists(select 1 from judge_assignments ja join matches m on m.ring_id=ja.ring_id and (ja.category_id is null or ja.category_id=m.category_id) where ja.id=assignment_id and ja.judge_id=auth.uid() and ja.active and m.id=match_id and m.status='awaiting_votes'));
create policy "published results public" on public.results for select using (published_at is not null or exists(select 1 from categories c join competitions cp on cp.id=c.competition_id where c.id=category_id and can_manage_event(cp.event_id)));
alter publication supabase_realtime add table public.events, public.rings, public.presentations, public.matches, public.flag_votes, public.scorecards, public.results, public.podiums;
